html:
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set customer = frappe.get_doc("Customer", doc.party) -%}
{%- set vat = doc.taxes[0] if doc.taxes else None -%}
{%- set tax = (vat.tax_amount if vat else 0) | float -%}
{%- set included = vat and vat.included_in_paid_amount -%}
{%- set net = (doc.paid_amount - tax) if included else doc.paid_amount -%}
{%- set gross = net + tax -%}
{%- set is_refund = doc.payment_type == "Pay" and doc.custom_advance_refund_against -%}
{%- set simplified = customer.custom_b2c -%}
<style>
  .ati { font-size: 12px; }
  .ati h2 { text-align: center; margin: 0 0 4px; font-size: 17px; }
  .ati .sub { text-align: center; color: #555; margin-bottom: 14px; }
  .ati table { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
  .ati th, .ati td { border: 1px solid #ccc; padding: 6px 8px; vertical-align: top; }
  .ati th { background: #f4f4f4; }
  .ati .ar { direction: rtl; text-align: right; }
  .ati .num { text-align: right; white-space: nowrap; }
  .ati .qr { text-align: center; margin-top: 10px; }
</style>
<div class="ati">
  {% if is_refund %}
    <h2>إشعار دائن &nbsp;|&nbsp; Credit Note</h2>
    <div class="sub">Refund of advance invoice {{ doc.custom_advance_refund_against }} &nbsp;·&nbsp; استرداد الدفعة المقدمة</div>
  {% else %}
    <h2>{% if simplified %}فاتورة ضريبية مبسطة - دفعة مقدمة &nbsp;|&nbsp; Simplified Advance Tax Invoice{% else %}فاتورة ضريبية - دفعة مقدمة &nbsp;|&nbsp; Advance Tax Invoice{% endif %}</h2>
    <div class="sub">Advance payment, to be deducted from the final invoice &nbsp;·&nbsp; دفعة مقدمة تخصم من الفاتورة النهائية</div>
  {% endif %}

  <table>
    <tr>
      <th>Invoice No. / رقم الفاتورة</th><td>{{ doc.name }}</td>
      <th>Date / التاريخ</th><td>{{ frappe.utils.formatdate(doc.posting_date) }}</td>
    </tr>
    <tr>
      <th>ZATCA status</th><td>{{ doc.custom_zatca_status or "" }}</td>
      <th>Order / الطلب</th>
      <td>{% for r in doc.references if r.reference_doctype == "Sales Order" %}{{ r.reference_name }}{% if not loop.last %}, {% endif %}{% endfor %}</td>
    </tr>
  </table>

  <table>
    <tr><th style="width:50%">Seller / البائع</th><th>Buyer / المشتري</th></tr>
    <tr>
      <td>
        <b>{{ company.company_name }}</b><br>
        {% if company.get("custom__company_name_in_arabic__") %}<span class="ar">{{ company.custom__company_name_in_arabic__ }}</span><br>{% endif %}
        VAT / الرقم الضريبي: {{ company.tax_id or "" }}<br>
        {{ company.custom_registration_type or "" }}: {{ company.custom_company_registration or "" }}
      </td>
      <td>
        <b>{{ customer.customer_name }}</b><br>
        {% if customer.tax_id %}VAT / الرقم الضريبي: {{ customer.tax_id }}<br>{% endif %}
        {% if customer.customer_primary_address %}
          {%- set addr = frappe.get_doc("Address", customer.customer_primary_address) -%}
          {{ addr.address_line1 or "" }} {{ addr.address_line2 or "" }}<br>{{ addr.city or "" }} {{ addr.pincode or "" }}
        {% endif %}
      </td>
    </tr>
  </table>

  <table>
    <tr>
      <th>Description / الوصف</th>
      <th class="num">Amount excl. VAT<br>المبلغ قبل الضريبة</th>
      <th class="num">VAT %</th>
      <th class="num">VAT / الضريبة</th>
      <th class="num">Total / الإجمالي</th>
    </tr>
    <tr>
      <td>{% if is_refund %}Refund of advance {{ doc.custom_advance_refund_against }}{% else %}Advance payment / دفعة مقدمة{% endif %}</td>
      <td class="num">{{ frappe.format(net, {"fieldtype": "Currency"}) }}</td>
      <td class="num">{{ vat.rate if vat else 0 }}%</td>
      <td class="num">{{ frappe.format(tax, {"fieldtype": "Currency"}) }}</td>
      <td class="num"><b>{{ frappe.format(gross, {"fieldtype": "Currency"}) }}</b></td>
    </tr>
  </table>

  {% if doc.ksa_einv_qr %}
  <div class="qr"><img src="{{ doc.ksa_einv_qr }}" style="width:130px;height:130px"></div>
  {% endif %}
</div>
